import SwiftUI

/// App colors. Each one is a color asset with light and dark variants (some also with an
/// Increased Contrast variant), generated by `scripts/design-tokens.py`, which also checks
/// their contrast. Views use these names only, never literal colors. Assets follow the iPhone's
/// appearance live; nothing in the app forces light or dark.
enum Theme {
    // Grounds and surfaces
    /// Screen background: white in light, deep green-black in dark.
    static let groundLight = Color(.ground)
    /// Slightly deeper ground behind the reading screen.
    static let ground = Color(.groundDeep)
    /// Cards and grouped rows (soft grey in light).
    static let surface = Color(.surface)
    /// Inputs and unselected chips on a card.
    static let field = Color(.field)
    static let border = Color(.border)
    static let divider = Color(.divider)

    // Text
    static let text = Color(.text)
    static let secondaryText = Color(.secondaryText)
    /// Empty progress step (decorative).
    static let pending = Color(.pending)

    // Primary: ink green
    static let accent = Color(.accent)
    /// Soft green fill for selected chips and notes.
    static let accentTint = Color(.accentTint)
    /// Text and icons on `accent`.
    static let onAccent = Color(.onAccent)

    // Secondary buttons ("soft glass" in light; see `SecondaryButtonStyle`)
    /// Translucent in light (drawn over a material), opaque in dark.
    static let secondaryFill = Color(.secondaryFill)
    /// The opaque fallback: Reduce Transparency, Increased Contrast and dark.
    static let secondaryFillOpaque = Color(.secondaryFillOpaque)
    static let secondaryBorder = Color(.secondaryBorder)

    // States
    static let success = Color(.success)
    /// 朱 vermilion, for destructive actions and errors.
    static let destructive = Color(.destructive)
    /// Text on `destructive`.
    static let onDestructive = Color(.onDestructive)
    /// Over-budget banner background, with `destructiveText` on it.
    static let destructiveFill = Color(.destructiveFill)
    static let destructiveText = Color(.destructiveText)
    /// "Check this field": amber border, fill and text.
    static let warning = Color(.warning)
    static let warningFill = Color(.warningFill)
    static let warningText = Color(.warningText)

    // Tax rate tags
    static let reducedRateFill = Color(.reducedRateFill)
    static let reducedRateText = Color(.reducedRateText)
    static let standardRateText = Color(.standardRateText)

    // Brand and overlays
    /// Ivory, the app icon's light color. The wordmark has its own dark-mode variant, so it
    /// no longer needs a plate.
    static let logoPlate = Color(.logoPlate)
    /// Dims the screen behind a confirm panel.
    static let scrim = Color(.scrim)
    /// Soft elevation under floating elements.
    static let shadow = Color(.shadow)
    /// Behind a full-screen photo, in both modes.
    static let photoBackdrop = Color.black
    /// Icons over a photo.
    static let onPhoto = Color.white
}
